/**
 * 计算所有点对的路径.
 * a 包含邻接矩阵, 其中
 * a[i][i] 假设为0.
 * d 包含最短路径的值.
 * 顶点从0开始编号; 所有的数组
 * 维数相等. 如果
 * d[i][i] 置为负值, 则负值圈存在.
 * 具体路径可以用 path[][] 来计算.
 * NOT_A_VERTEX 为 -1
 */
void allPairs( const matrix<int> & a, matrix<int> & d, matrix<int> & path )
{
    int n = a.numrows();

    // 初始化d 和 path
    for( int i = 0; i < n; ++i )
        for( int j = 0; j < n; ++j )
        {
            d[i][j] = a[i][j];
            path[i][j] = NOT_A_VERTEX;
        }

    for( int k = 0; k < n; ++k )
        // 把每个顶点看作为一个中间节点
        for( int i = 0; i < n; ++i )
            for( int j = 0; j < n; ++j )
                if( d[i][k] + d[k][j] < d[i][j] )
                {
                    // 更新最短路径
                    d[i][j] = d[i][k] + d[k][j];
                    path[i][j] = k;
